function frame(object=content){object.updateMatrixWorld(true);const b=new THREE.Box3().setFromObject(object);if(b.isEmpty())return;const center=b.getCenter(new THREE.Vector3()),size=b.getSize(new THREE.Vector3());const radius=Math.max(size.length()/2,1);const distance=radius/Math.sin(THREE.MathUtils.degToRad(21))*1.1;orbit.target.copy(center);camera.position.copy(center).add(new THREE.Vector3(1,.65,1.1).normalize().multiplyScalar(distance));camera.near=Math.max(.01,radius/2000);camera.far=Math.max(10000,distance*20);camera.updateProjectionMatrix();orbit.update();}
