 const picked=resolvePick(nodeHit||hits[0],mode);select(picked?.entry||null,true,event.ctrlKey||event.metaKey);if(picked){tree.reveal(picked.entry);if(picked.slot&&$('surface-slot').querySelector('option')&&[...$('surface-slot').options].some(o=>o.value===picked.slot)){$('surface-slot').value=picked.slot;$('surface-slot').dispatchEvent(new Event('change'));}message((picked.entry.owner?'Pieza: ':'Objeto: ')+picked.entry.name+(picked.slot?' ? Material: '+picked.slot:''));}

