for(const [k,title] of [['position','Posición · metros'],['rotation','Rotación · grados'],['scale','Escala']]){const wrap=document.createElement('div');wrap.className='vector';const label=document.createElement('label');label.textContent=title;const axes=document.createElement('div');axes.className='axes';for(const a of ['X','Y · altura','Z']){const s=document.createElement('span');s.textContent=a;axes.append(s);}const row=document.createElement('div');for(let i=0;i<3;i++){const input=document.createElement('input');input.id=`${k}-${i}`;input.type='number';input.step=k==='rotation'?'1':'.1';input.setAttribute('aria-label',title+' '+['X','Y','Z'][i]);input.onchange=()=>{if(!selected||editLocked(selected))return;let v=Number(input.value);if(!Number.isFinite(v)||Math.abs(v)>=1e7||(k==='scale'&&v<.001)){select(selected);return;}if(k==='rotation')v=THREE.MathUtils.degToRad(v);selected.object[k][['x','y','z'][i]]=v;select(selected);commit();};row.append(input);}wrap.append(label,axes,row);$('transform-fields').append(wrap);}
