function removeSelected(target=selected){if(!target||editLocked(target)||busy)return;if(target.owner){target.object.visible=false;touchPart(target);const owner=target.owner;select(owner,true);renderObjects();commit();message(target.name+' quitado de la escena. Deshacer lo recupera.');return;}const removed=new Set([target,...descendants(target)]);select(null);for(const e of removed){e.object.userData.sceneEffect?.dispose();e.object.removeFromParent();}entries=entries.filter(v=>!removed.has(v));renderObjects();commit();message(target.name+' quitado de la escena. Deshacer lo recupera.');}$('remove').onclick=()=>removeSelected();
