function chosenRoots(){return entries.filter(e=>selectedIds.has(e.id)&&!entries.some(p=>selectedIds.has(p.id)&&descendants(p).includes(e)));}
function checkedRoots(){const chosen=chosenRoots();if(busy||chosen.length<2||selected?.owner){message('Usá Ctrl + clic para elegir al menos dos objetos completos del árbol.');return null;}if(chosen.some(editLocked)){message('Desbloqueá los objetos y sus piezas antes de agrupar o fusionar.');return null;}if(chosen.some(e=>(e.parent||null)!==(chosen[0].parent||null))){message('Elegí objetos que estén en la misma rama del árbol.');return null;}return chosen;}
function localPose(object,parent){object.updateWorldMatrix(true,false);parent.updateWorldMatrix(true,false);const matrix=new THREE.Matrix4().multiplyMatrices(new THREE.Matrix4().copy(parent.matrixWorld).invert(),object.matrixWorld),position=new THREE.Vector3(),rotation=new THREE.Quaternion(),scale=new THREE.Vector3();matrix.decompose(position,rotation,scale);const rebuilt=new THREE.Matrix4().compose(position,rotation,scale);if(matrix.elements.some((v,i)=>Math.abs(v-rebuilt.elements[i])>1e-4)||scale.toArray().some(v=>v<.001))throw new Error('Esta combinación de rotación y escala requiere aplicar las transformaciones antes de reorganizar las piezas.');return {position:position.toArray(),rotation:new THREE.Euler().setFromQuaternion(rotation).toArray().slice(0,3),scale:scale.toArray()};}
function setPose(object,p){object.position.fromArray(p.position);object.rotation.set(...p.rotation);object.scale.fromArray(p.scale);}
async function groupSelection(){const chosen=checkedRoots();if(!chosen)return;const parent=chosen[0].object.parent;const bounds=new THREE.Box3();for(const e of chosen)bounds.union(new THREE.Box3().setFromObject(e.object));const center=parent.worldToLocal(bounds.getCenter(new THREE.Vector3()));const group=await makeEntry({id:uid(),kind:'group',parent:chosen[0].parent||null,name:'Grupo '+(entries.filter(e=>e.kind==='group').length+1),asset:chosen[0].asset,node:'',base:false,locked:false,visible:true,position:center.toArray(),rotation:[0,0,0],scale:[1,1,1]});parent.add(group.object);for(const e of chosen){group.object.attach(e.object);e.parent=group.id;}renderObjects();select(group,true);tree.expand(group.id);commit();message('Grupo creado. Las piezas siguen siendo independientes.');}
function ungroupSelection(){const group=selected;if(!group||group.kind!=='group'||editLocked(group)||busy)return message('Seleccioná un grupo desbloqueado, con sus piezas desbloqueadas.');try{const children=entries.filter(e=>e.parent===group.id),parent=group.object.parent,poses=children.map(e=>localPose(e.object,parent));children.forEach((e,i)=>{parent.add(e.object);setPose(e.object,poses[i]);e.parent=group.parent||null;});group.object.removeFromParent();entries=entries.filter(e=>e!==group);select(null);renderObjects();if(children[0])select(children[0],true);commit();message('Grupo desarmado; se conservaron las posiciones de sus piezas.');}catch(e){message(e.message);}}
async function mergeSelection(){let chosen=chosenRoots();if(selected?.kind==='group'&&chosen.length===1)chosen=entries.filter(e=>e.parent===selected.id);else chosen=checkedRoots();if(!chosen||chosen.length<2||chosen.some(editLocked))return message('Elegí al menos dos objetos o un grupo con dos piezas desbloqueadas.');if(chosen.some(e=>!visibleInScene(e)))return message('Mostrá los objetos antes de fusionarlos.');const parent=chosen[0].object.parent,owner=chosen[0].parent||null,leaves=chosen.flatMap(e=>e.kind==='group'?descendants(e).filter(c=>c.kind!=='group'):[e]);if(leaves.some(e=>e.kind==='effect'))return message('Los efectos animados se pueden agrupar, pero no fusionar como mallas.');if(leaves.length<2)return message('La fusión necesita al menos dos mallas.');setBusy(true,'Fusionando mallas…');try{const bounds=new THREE.Box3();for(const e of chosen)bounds.union(new THREE.Box3().setFromObject(e.object));const center=parent.worldToLocal(bounds.getCenter(new THREE.Vector3()));const components=leaves.map(e=>{const meta=structuredClone(currentMeta(e));Object.assign(meta,localPose(e.object,parent));meta.position=meta.position.map((v,i)=>v-center.getComponent(i));meta.parent=null;return meta;});const e=await makeEntry({id:uid(),name:'Fusión de '+leaves.length+' piezas',kind:'merged',parent:owner,asset:leaves[0].asset,node:'',base:false,locked:false,visible:true,position:center.toArray(),rotation:[0,0,0],scale:[1,1,1],components});parent.add(e.object);const removed=new Set(chosen.flatMap(c=>[c,...descendants(c)]));for(const c of removed)c.object.removeFromParent();entries=entries.filter(c=>!removed.has(c));renderObjects();select(e,true);setBusy(false);commit();message('Piezas fusionadas en una malla. Deshacer recupera los objetos originales.');}catch(e){setBusy(false);message('No se fusionó: '+e.message);}}
$('frame').onclick=()=>{frame(selected?.object||content);persistView();};$('home').onclick=()=>{frame();persistView();};$('undo').onclick=()=>undo(-1);$('redo').onclick=()=>undo(1);
$('search').oninput=$('filter').onchange=()=>{libraryPage=1;library();};
async function saveVersion(){const project=JSON.stringify(snapshot());const r=await fetch('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:project});const result=await r.json();if(!r.ok)throw new Error(result.error);return result.saved;}
$('scene').onchange=async()=>{if(busy)return;const next=$('scene').value;try{if(saved!==JSON.stringify(snapshot())){await saveVersion();saved=JSON.stringify(snapshot());mark();}if(next==='project:'+gardenProject){const url=new URL(location.href);url.searchParams.set('project',gardenProject);url.searchParams.set('ambientes','1');location.assign(url.href);return;}activeSceneProject='';await loadScene(next);}catch(e){syncSceneSelector();message('No se cambió la escena: '+e.message);}};
function suggestedProjectName(){return (currentFileName||('l2-'+(definition?.id||'escenario')+'.json')).replace(/[^\p{L}\p{N}_. -]/gu,'-');}
function downloadProject(text,name){const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function saveProject(forceAs=false){const text=JSON.stringify(snapshot(),null,2);if(window.showSaveFilePicker){if(forceAs||!currentFileHandle)currentFileHandle=await window.showSaveFilePicker({suggestedName:suggestedProjectName(),types:[{description:'Proyecto del Taller de escenarios',accept:{'application/json':['.json']}}]});const writable=await currentFileHandle.createWritable();await writable.write(text);await writable.close();currentFileName=currentFileHandle.name||suggestedProjectName();}else{currentFileName=suggestedProjectName();downloadProject(text,currentFileName);}saved=JSON.stringify(snapshot());mark();localStorage.setItem('l2-scene-editor-last-file',currentFileName);message('Proyecto guardado: '+currentFileName);return currentFileName;}
$('save').onclick=async()=>{try{await saveProject(true);}catch(e){if(e.name!=='AbortError')message('No se pudo guardar: '+e.message);}};
$('export').onclick=()=>{const name=suggestedProjectName().replace(/\.json$/i,'')+'-copia.json';downloadProject(JSON.stringify(snapshot(),null,2),name);message('Copia exportada: '+name);};
async function openProjectFile(file,handle=null){if(file.size>3e6)throw new Error('Proyecto demasiado grande.');const project=JSON.parse(await file.text());validProject(project);if(saved!==JSON.stringify(snapshot()))await saveVersion();await restore(project);history=[];historyIndex=-1;commit();saved=JSON.stringify(snapshot());currentFileHandle=handle;currentFileName=file.name;mark();message('Proyecto abierto: '+file.name);}
$('open').onclick=async()=>{try{if(window.showOpenFilePicker){const [handle]=await window.showOpenFilePicker({multiple:false,types:[{description:'Proyecto del Taller de escenarios',accept:{'application/json':['.json']}}]});await openProjectFile(await handle.getFile(),handle);}else $('file').click();}catch(e){if(e.name!=='AbortError')message('No se pudo abrir: '+e.message);}};
$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{await openProjectFile(file);}catch(e){message('No se pudo abrir: '+e.message);}finally{$('file').value='';}};
$('new-project').onclick=async()=>{if(busy)return;if(saved!==JSON.stringify(snapshot())&&!confirm('Hay cambios sin guardar. ¿Querés empezar un proyecto nuevo y descartarlos?'))return;currentFileHandle=null;currentFileName='';localStorage.removeItem(draftKey);await loadScene(definition?.id||'gludio');message('Proyecto nuevo. Usá Guardar como… para elegir nombre y ubicación.');};
window.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable||busy||!$('asset-window').hidden)return;const key=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&key==='z'){e.preventDefault();undo(e.shiftKey?1:-1);return;}if(e.ctrlKey&&key==='y'){e.preventDefault();undo(1);return;}if((e.ctrlKey||e.metaKey)&&key==='s'){e.preventDefault();saveProject(false).catch(error=>{if(error.name!=='AbortError')message('No se pudo guardar: '+error.message);});return;}if(e.ctrlKey||e.metaKey||e.altKey)return;if(key==='escape'){cancelPlacement();select(null);}if(key==='f'){e.preventDefault();focusSelected();}if(key==='c'){e.preventDefault();if(!e.repeat)bringSelected();}if(key==='q'){e.preventDefault();if(!e.repeat){showNodes=!showNodes;$('show-nodes').checked=showNodes;message(showNodes?'Nodos de objetos visibles.':'Solo se muestra el nodo seleccionado.');}}const mode={w:'translate',e:'rotate',r:'scale'}[key];if(mode){e.preventDefault();document.querySelector(`[data-mode="${mode}"]`).click();}if(key==='delete')$('remove').click();});
window.addEventListener('beforeunload',e=>{if(definition&&saved!==JSON.stringify(snapshot())){e.preventDefault();e.returnValue='';}});
async function start(){await atmosphere.ready;data=await(await fetch('/api/data')).json();try{previousDraft=JSON.parse(localStorage.getItem(draftKey));validProject(previousDraft);}catch{previousDraft=null;}for(const s of data.scenes){const o=document.createElement('option');o.value=s.id;o.textContent=s.title;$('scene').append(o);}const gardenOption=document.createElement('option');gardenOption.value='project:'+gardenProject;gardenOption.textContent='Gludio \u00b7 Jard\u00edn de las Brisas (animado)';$('scene').append(gardenOption);assetLibrary.setCategories(data.assets.map(a=>a.category));library();if(requestedProject){let project=previousDraft;if(!project){const response=await fetch('/api/projects/'+encodeURIComponent(requestedProject));if(!response.ok)throw new Error('No se encontró el proyecto '+requestedProject);project=await response.json();validProject(project);}await restore(project);history=[];historyIndex=-1;commit();saved=JSON.stringify(snapshot());currentFileName=requestedProject;syncSceneSelector();mark();document.title=requestedProject.replace(/\.json$/i,'')+' · Taller de escenarios';message('Proyecto abierto: '+requestedProject+(previousDraft?' · borrador recuperado.':'.'));return;}await loadScene('gludio');if(previousDraft){await restore(previousDraft);history=[];historyIndex=-1;commit();message('Borrador anterior recuperado. Podés guardar una versión para conservarlo en disco.');}}
const surfacePanel=createSurfacePanel({parent:$('terrain-controls'),getSelected:()=>['group','effect'].includes(selected?.kind)?null:selected,commit:e=>{touchPart(e);commit();},message,isBusy:()=>busy,canEdit:e=>!editLocked(e),onWorking:value=>setBusy(value),apply:(e,edits)=>{const owner=e.owner||e,parts=[...(owner.partEdits?.values()||[])].filter(p=>p.path!==e.path);if(e.owner)parts.push({path:e.path,surfaces:edits});return applyTreeSurfaces(owner.object,e.owner?owner.surfaces||[]:edits,parts);}});
$('surface-slot').addEventListener('change',()=>{selectedSlot=$('surface-slot').value;});
const tree=createSceneTree({host:document.querySelector('main'),getEntries:()=>entries,getParts:partChildren,isSelected:e=>selectedIds.has(e.id),isLocked:editLocked,isVisible:visibleInScene,onSelect:(e,add)=>select(e,true,add),onContextMenu:(e,event)=>{event.preventDefault();if(!editLocked(e))showRemoveMenu(e,event.clientX,event.clientY);},onToggle:(e,k)=>{if(busy)return;if(k==='locked'){changeLocks('selection',!editLocked(e),e);return;}e.object.visible=!e.object.visible;touchPart(e);renderObjects();commit();},onGroup:groupSelection,onUngroup:ungroupSelection,onMerge:mergeSelection});
const lockUI=createLockControls({studio,tree:tree.element,getSelected:()=>selected,getBranch:branchTarget,isLocked:editLocked,getReason:lockReason,isBusy:()=>busy,onAction:changeLocks});
